package com.bank.runtime;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.logging.*;

public class NightlyBatch {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        InterestCalculator calc = new InterestCalculator();

        // Run the SAME hot method many times so the JIT compiles it to native code.
        int totalTransfers = 200_000;
        long start = System.nanoTime();
        BigDecimal last = BigDecimal.ZERO;
        for (int i = 0; i < totalTransfers; i++) {
            last = calc.calculateInterest(rajesh.getBalance(), new BigDecimal("3.5"));
        }
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;

        log.info(() -> "Ran interest calc " + totalTransfers + " times");
        final BigDecimal shown = last;
        log.info(() -> "Interest per run for " + rajesh.getAccountId() + " = " + shown);
        log.info(() -> "Total time ms (interpret warmup + JIT native) = " + elapsedMs);
    }
}

