class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── Would be InterestCalculator.java in a real project ───
class InterestCalculator {
    // This method is called 200,000 times, so it becomes a HOT method
    // and the JIT compiler turns it into native machine code.
    BigDecimal calculateInterest(BigDecimal principal, BigDecimal annualRatePercent) {
        return principal.multiply(annualRatePercent)
                        .divide(new BigDecimal("100"), 2, RoundingMode.HALF_EVEN)
                        .divide(new BigDecimal("12"), 2, RoundingMode.HALF_EVEN);
    }
}
